"use strict";
const WargaState = (() => {
    const KK_LIST = [],  // ← tidak dari window.__KK_LIST__ lagi
        e = window.__RT_LIST__ || [],
        n = window.__ROLE__ || "rt",
        PERUMAHAN_LIST = window.__PERUMAHAN_LIST__ || [],
        CLUSTER_LIST = window.__CLUSTER_LIST__ || [];

    let a = null,
        r = !1;

    function o(t) {
        return String(t ?? "")
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;");
    }

    return {
        KK_LIST,
        RT_LIST: e,
        ROLE: n,
        PERUMAHAN_LIST,
        CLUSTER_LIST,
        dom: {
            get kkClusterFilter()   { return document.getElementById("kkClusterFilter"); },
            //get kkLoading()         { return document.getElementById("kkLoading"); },
            get kkGrid()            { return document.getElementById("kkGrid"); },
            get kkEmpty()           { return document.getElementById("kkEmpty"); },
            get kkSearch()          { return document.getElementById("kkSearch"); },
            get kkPagination()      { return document.getElementById("kkPagination"); },
            get panelAnggota()      { return document.getElementById("panelAnggota"); },
            get panelKkNama()       { return document.getElementById("panelKkNama"); },
            get panelKkInfo()       { return document.getElementById("panelKkInfo"); },
            get btnTutupPanel()     { return document.getElementById("btnTutupPanel"); },
            get btnTambahKk()       { return document.getElementById("btnTambahKk"); },
            get btnTambahWrg()      { return document.getElementById("btnTambahWarga"); },
            get tabelBody()         { return document.getElementById("tabelAnggotaBody"); },
            get infoTotal()         { return document.getElementById("infoTotal"); },
        },
        get activeKk() { return a; },
        set activeKk(t) { a = t; },
        get isLoading() { return r; },
        set isLoading(t) { r = t; },
        esc: o,
        rowLoading: function () {
            return '<tr><td colspan="7" class="text-center py-4">\n            <div class="spinner-border spinner-border-sm text-primary"></div>\n            <span class="ms-2 text-muted small">Memuat...</span>\n        </td></tr>';
        },
        rowError: function (t = "Gagal memuat data.") {
            return `<tr><td colspan="7" class="text-center py-4 text-danger small">${t}</td></tr>`;
        },
        rowKosong: function (t) {
            return `<tr><td colspan="7" class="text-center py-5 text-muted">\n            <i class="bx bx-user-x d-block fs-3 mb-2 opacity-50"></i>${o(t)}\n        </td></tr>`;
        },
    };
})();